/**
 * @file test_fuzz.cpp
 * @brief Deterministic fuzz and negative-test driver for the host-only engine paths.
 *
 * Feeds truncated, malformed, absurd-length, and unknown-type input to the
 * subsystems that run on the host, and requires that every malformed input be
 * rejected with an explicit error code rather than a defaulted value, a silent
 * zero scale, an allocation driven by a file-supplied length, or an
 * out-of-bounds read. Cases are enumerated exhaustively or generated by a
 * fixed-seed generator, so a failure is always reproducible: the corpus is
 * byte-for-byte identical on every run and every host.
 *
 * Coverage:
 *  - GGUF truncation at every byte offset of a well-formed file, of a
 *    metadata-only file, and of a zero-tensor file. Cutting at every offset
 *    necessarily cuts inside every length prefix, every key/value pair, every
 *    tensor-header field, and every payload byte, and each cut is attributed to
 *    the field it lands in so coverage is reported rather than inferred;
 *  - GGUF structure corruption at every byte of the header and of the payload;
 *  - unknown metadata value types, unknown tensor types, absurd counts,
 *    dimensions, offsets, and string lengths;
 *  - the nil-pointer and empty-buffer boundary of every public entry point;
 *  - ROCmFP4 nibble decode: all 256 byte values at every byte position of a
 *    packed block, in both layouts, including scale byte 0x7F and every byte
 *    with the sign bit set, each accepted value checked against an independent
 *    re-derivation of the format;
 *  - the CPU reference decode path over absurd element counts;
 *  - SHA-256 across every length class that exercises a distinct padding path;
 *  - the trace-recorder host path, including every invalid configuration;
 *  - the on-disk reader boundary through `GgufReader`, where a manifest accepted
 *    by `gguf_validate_tensors` must also have every declared tensor fully
 *    readable inside the file.
 *
 * @note The driver never sizes a buffer from a length read out of the file under
 *       test. Every buffer is sized from a constant or from a field the driver
 *       wrote itself, so a hostile length cannot drive an allocation.
 * @note The randomised corpus comes from `Lcg`, a fixed-seed linear congruential
 *       generator. It does not depend on the C library's `rand`, on a random
 *       device, or on the run's start time, so the emitted cases are identical
 *       everywhere.
 * @note `gguf_validate_tensors` multiplies a fixed-width tensor's element count
 *       by its width without an overflow check, so an extreme dimension wraps
 *       the byte size and the manifest is reported valid. The driver feeds the
 *       whole spectrum and holds the engine to the invariant that does hold end
 *       to end: whatever passes validation must be fully readable inside the
 *       file, and a tensor that is not must be refused by `GgufReader::read_tensor`.
 * @warning This driver is the negative half of the unit suites. A change that
 *          relaxes a required rejection into a tolerated default fails here;
 *          that is the intended behaviour, not a test bug.
 */

#include "rocminfer/format_registry.hpp"
#include "rocminfer/gguf_reader.hpp"
#include "rocminfer/profiler.hpp"
#include "rocminfer/rocmfp4_reference.hpp"
#include "rocminfer/sha256.hpp"

#include <cerrno>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <array>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace {

int g_failures = 0;         ///< Failed assertions across every section.
std::uint64_t g_cases = 0;  ///< Malformed inputs evaluated and rejected.

void check(bool condition, const char* expression, int line) {
    if (!condition) {
        std::fprintf(stderr, "FAIL line %d: %s\n", line, expression);
        ++g_failures;
    }
}

#define CHECK(expr) check((expr), #expr, __LINE__)

/**
 * @brief Fixed-seed linear congruential generator driving the fuzz corpus.
 *
 * The multiplier and increment are the constants of a well-known 64-bit LCG
 * stream and the seed is fixed, so the emitted sequence is identical on every
 * platform, every run, and every C library. That is what makes a failure here
 * reproducible instead of intermittent.
 */
class Lcg {
public:
    /**
     * @brief Seed the stream.
     * @param[in] seed Initial state; 0 is remapped to 1 so the stream never stalls.
     * @post The first `next()` value is a deterministic function of `seed`.
     */
    explicit Lcg(std::uint64_t seed) noexcept : state_(seed == 0 ? 1u : seed) {}

    /**
     * @brief Advance the stream and return the next value.
     * @return The generator's new state.
     */
    std::uint64_t next() noexcept {
        state_ = state_ * 6364136223846793005ULL + 1442695040888963407ULL;
        return state_;
    }

    /**
     * @brief Return a value in `[0, bound)`.
     * @param[in] bound Exclusive upper bound; must be non-zero.
     * @return A value below `bound`, or 0 when `bound` is 0.
     * @pre `bound != 0`.
     */
    std::uint64_t below(std::uint64_t bound) noexcept {
        return bound == 0 ? 0u : next() % bound;
    }

private:
    std::uint64_t state_ = 1;  ///< Current state; never exposed to callers.
};

// ---------------------------------------------------------------------------
// GGUF assembly
// ---------------------------------------------------------------------------

/**
 * @brief Role of one byte in a GGUF file, used to attribute truncations.
 *
 * The labels let the truncation sweep report which field every rejected cut
 * landed in, so coverage of the length prefixes, the key/value pairs, the
 * tensor-header fields, and the payload is reported rather than inferred.
 */
enum class FieldRole : std::uint8_t {
    kHeader = 0,   ///< Magic, version, or a declared count.
    kLengthPrefix, ///< A string length prefix.
    kKeyBytes,     ///< The bytes of a key or a tensor name.
    kValueType,    ///< A value-type tag.
    kScalarValue,  ///< The payload of a scalar value.
    kArrayCount,   ///< An array element count.
    kArrayValue,   ///< The payload of an array value.
    kDimCount,     ///< `n_dims`.
    kDimValue,     ///< A dimension extent.
    kTensorType,   ///< A `ggml_type` tag.
    kTensorOffset, ///< A payload offset.
    kPadding,      ///< Alignment padding.
    kPayload,      ///< Tensor payload bytes.
    kRoleCount     ///< Sentinel; not a role.
};

/// Human-readable name of a field role.
const char* role_name(FieldRole role) noexcept {
    switch (role) {
        case FieldRole::kHeader:       return "header";
        case FieldRole::kLengthPrefix: return "length-prefix";
        case FieldRole::kKeyBytes:     return "key-or-name";
        case FieldRole::kValueType:    return "value-type";
        case FieldRole::kScalarValue:  return "scalar-value";
        case FieldRole::kArrayCount:   return "array-count";
        case FieldRole::kArrayValue:   return "array-value";
        case FieldRole::kDimCount:     return "dim-count";
        case FieldRole::kDimValue:     return "dim-value";
        case FieldRole::kTensorType:   return "tensor-type";
        case FieldRole::kTensorOffset: return "tensor-offset";
        case FieldRole::kPadding:      return "padding";
        case FieldRole::kPayload:      return "payload";
        case FieldRole::kRoleCount:    break;
    }
    return "invalid";
}

/**
 * @brief Byte-exact GGUF writer that records the role of every byte it emits.
 *
 * The writer never repairs, clamps, or reorders its input. A writer that
 * silently fixed a malformed field could never produce the rejection cases this
 * driver must feed, so malformed values pass through unchanged.
 */
class GgufWriter {
public:
    /// Append `count` raw bytes tagged as `role`.
    void raw(const void* source, std::size_t count, FieldRole role) {
        const auto* first = static_cast<const std::uint8_t*>(source);
        bytes_.insert(bytes_.end(), first, first + count);
        roles_.insert(roles_.end(), count, role);
    }

    /// Append a little-endian 32-bit value.
    void u32(std::uint32_t value, FieldRole role) {
        std::uint8_t buffer[4];
        for (std::size_t i = 0; i < sizeof(buffer); ++i) {
            buffer[i] = static_cast<std::uint8_t>((value >> (8u * i)) & 0xFFu);
        }
        raw(buffer, sizeof(buffer), role);
    }

    /// Append a little-endian 64-bit value.
    void u64(std::uint64_t value, FieldRole role) {
        std::uint8_t buffer[8];
        for (std::size_t i = 0; i < sizeof(buffer); ++i) {
            buffer[i] = static_cast<std::uint8_t>((value >> (8u * i)) & 0xFFu);
        }
        raw(buffer, sizeof(buffer), role);
    }

    /**
     * @brief Append a length-prefixed string and record the prefix offset.
     * @param[in] value NUL-terminated text; may be empty but not NULL.
     * @param[in] role  Role of the string bytes themselves.
     */
    void str(const char* value, FieldRole role) {
        const std::size_t length = std::strlen(value);
        length_prefixes_.push_back(bytes_.size());
        u64(static_cast<std::uint64_t>(length), FieldRole::kLengthPrefix);
        raw(value, length, role);
    }

    /// Append zero padding up to the default GGUF alignment.
    void pad() {
        while (bytes_.size() % rocminfer::GGUF_DEFAULT_ALIGNMENT != 0) {
            const std::uint8_t zero = 0;
            raw(&zero, 1, FieldRole::kPadding);
        }
    }

    /// Bytes assembled so far.
    const std::vector<std::uint8_t>& bytes() const noexcept { return bytes_; }

    /// Role of every byte in `bytes()`; the two vectors have equal length.
    const std::vector<FieldRole>& roles() const noexcept { return roles_; }

    /// Offset of every length prefix written so far.
    const std::vector<std::size_t>& length_prefixes() const noexcept {
        return length_prefixes_;
    }

    /// Current byte count, used to record field offsets while writing.
    std::size_t size() const noexcept { return bytes_.size(); }

private:
    std::vector<std::uint8_t> bytes_;           ///< Assembled file bytes.
    std::vector<FieldRole> roles_;              ///< Role of each byte in `bytes_`.
    std::vector<std::size_t> length_prefixes_;  ///< Offset of each length prefix.
};

/**
 * @brief One GGUF key/value-table entry written verbatim by the fuzz driver.
 */
struct MetadataSpec {
    const char* key = "k";                  ///< Key string.
    std::uint32_t raw_type = 0;             ///< Raw value-type tag.
    std::uint64_t scalar = 0;               ///< Word written for a fixed-width scalar.
    const char* string_value = nullptr;     ///< Payload written for a string value.
    std::uint32_t array_element_type = 0;   ///< Element type when `raw_type` is an array.
    std::uint64_t array_length = 0;         ///< Element count when `raw_type` is an array.
    std::vector<std::uint8_t> array_bytes;  ///< Element payload written for an array.
};

/**
 * @brief One GGUF tensor-table entry written verbatim by the fuzz driver.
 */
struct TensorSpec {
    const char* name = "w";         ///< Tensor name.
    std::uint32_t n_dims = 1;      ///< Dimension count.
    std::uint64_t dim = 4;         ///< Dimension extent.
    std::uint32_t type_id = 0;     ///< Raw `ggml_type`.
    std::uint64_t offset = 0;      ///< Payload offset.
};

/**
 * @brief A GGUF header written verbatim by the fuzz driver.
 */
struct HeaderSpec {
    std::uint32_t version = 3;       ///< Container version.
    std::uint64_t tensor_count = 0;  ///< Declared tensor count.
    std::uint64_t kv_count = 0;      ///< Declared key/value count.
};

/**
 * @brief A GGUF file assembled by the fuzz driver, with its field map.
 */
struct AssembledGguf {
    std::vector<std::uint8_t> bytes;  ///< Complete file bytes.
    std::vector<FieldRole> roles;     ///< Role of each byte; same length as `bytes`.
    std::size_t structure_end = 0;    ///< Offset just past the declared structure.
    std::size_t payload_start = 0;    ///< Offset of the first payload byte.
    std::vector<std::size_t> length_prefixes;       ///< Offset of every length prefix.
    std::vector<std::size_t> kv_field_offsets;      ///< Offset of every key/value field.
    std::vector<std::size_t> tensor_field_offsets;  ///< Offset of every tensor-header field.
    std::vector<std::size_t> header_offsets;        ///< Offset of magic, version, and both counts.
};

/**
 * @brief Assemble a complete GGUF file from caller-supplied header and tables.
 * @param[in] header   Magic, version, and both declared counts.
 * @param[in] metadata Key/value entries, written before the tensor table.
 * @param[in] tensors  Tensor-table entries, written after the metadata.
 * @param[in] payload_bytes Bytes appended after alignment padding; 0 produces a
 *                         manifest-only file.
 * @return The assembled file and a map of every field offset.
 * @note The payload region is zero-filled. Extent validation reads declared
 *       sizes rather than payload content, so zeros are sufficient.
 */
AssembledGguf assemble_gguf(const HeaderSpec& header,
                            const std::vector<MetadataSpec>& metadata,
                            const std::vector<TensorSpec>& tensors,
                            std::size_t payload_bytes) {
    AssembledGguf out;
    GgufWriter writer;

    out.header_offsets.push_back(writer.size());
    writer.u32(rocminfer::GGUF_MAGIC, FieldRole::kHeader);
    out.header_offsets.push_back(writer.size());
    writer.u32(header.version, FieldRole::kHeader);
    out.header_offsets.push_back(writer.size());
    writer.u64(header.tensor_count, FieldRole::kHeader);
    out.header_offsets.push_back(writer.size());
    writer.u64(header.kv_count, FieldRole::kHeader);

    for (const MetadataSpec& entry : metadata) {
        out.kv_field_offsets.push_back(writer.size());
        writer.str(entry.key, FieldRole::kKeyBytes);
        out.kv_field_offsets.push_back(writer.size());
        writer.u32(entry.raw_type, FieldRole::kValueType);
        if (entry.raw_type ==
            static_cast<std::uint32_t>(rocminfer::GgufValueType::kArray)) {
            out.kv_field_offsets.push_back(writer.size());
            writer.u32(entry.array_element_type, FieldRole::kValueType);
            out.kv_field_offsets.push_back(writer.size());
            writer.u64(entry.array_length, FieldRole::kArrayCount);
            writer.raw(entry.array_bytes.data(), entry.array_bytes.size(),
                       FieldRole::kArrayValue);
        } else if (entry.raw_type ==
                   static_cast<std::uint32_t>(rocminfer::GgufValueType::kString)) {
            writer.str(entry.string_value == nullptr ? "" : entry.string_value,
                       FieldRole::kScalarValue);
        } else {
            writer.u64(entry.scalar, FieldRole::kScalarValue);
        }
    }
    const std::size_t kv_end = writer.size();

    for (const TensorSpec& entry : tensors) {
        out.tensor_field_offsets.push_back(writer.size());
        writer.str(entry.name, FieldRole::kKeyBytes);
        out.tensor_field_offsets.push_back(writer.size());
        writer.u32(entry.n_dims, FieldRole::kDimCount);
        for (std::uint32_t d = 0; d < entry.n_dims; ++d) {
            out.tensor_field_offsets.push_back(writer.size());
            writer.u64(entry.dim, FieldRole::kDimValue);
        }
        out.tensor_field_offsets.push_back(writer.size());
        writer.u32(entry.type_id, FieldRole::kTensorType);
        out.tensor_field_offsets.push_back(writer.size());
        writer.u64(entry.offset, FieldRole::kTensorOffset);
    }
    const std::size_t tensor_table_end = writer.size();

    writer.pad();
    out.payload_start = writer.size();
    if (payload_bytes > 0) {
        const std::vector<std::uint8_t> payload(payload_bytes, 0);
        writer.raw(payload.data(), payload_bytes, FieldRole::kPayload);
    }

    out.bytes = writer.bytes();
    out.roles = writer.roles();
    out.structure_end = header.tensor_count > 0 ? tensor_table_end : kv_end;
    out.length_prefixes = writer.length_prefixes();
    return out;
}

// ---------------------------------------------------------------------------
// Assertion helpers
// ---------------------------------------------------------------------------

/// Require that a malformed input produce exactly `expected`.
void expect_reject(int status, int expected, const char* what) {
    ++g_cases;
    if (status != expected) {
        std::fprintf(stderr, "FAIL: %s returned %d, expected %d\n", what, status, expected);
        ++g_failures;
    }
}

/// Require that a well-formed input produce success.
void expect_accept(int status, const char* what) {
    ++g_cases;
    if (status != 0) {
        std::fprintf(stderr, "FAIL: %s returned %d, expected 0\n", what, status);
        ++g_failures;
    }
}

/**
 * @brief Require that a malformed manifest be refused by `gguf_parse`.
 * @param[in] bytes Candidate buffer, possibly truncated or corrupted.
 * @param[in] what  Case label printed on failure.
 */
void expect_parse_reject(const std::vector<std::uint8_t>& bytes, const char* what) {
    rocminfer::GgufFile file;
    expect_reject(rocminfer::gguf_parse(&file, bytes.data(), bytes.size()), ERANGE, what);
}

/**
 * @brief Require that a malformed extent be refused by `gguf_validate_tensors`.
 *
 * A manifest whose declared tensors do not fit the file must not validate, so a
 * zero return here is a failure.
 *
 * @param[in] bytes Candidate buffer holding a complete manifest.
 * @param[in] what  Case label printed on failure.
 */
void expect_validate_reject(const std::vector<std::uint8_t>& bytes, const char* what) {
    rocminfer::GgufFile file;
    const int parse_status = rocminfer::gguf_parse(&file, bytes.data(), bytes.size());
    if (parse_status != 0) {
        expect_reject(parse_status, ERANGE, what);
        return;
    }
    expect_reject(rocminfer::gguf_validate_tensors(file, bytes.size(), bytes.size()),
                  ERANGE, what);
}

/**
 * @brief Require the end-to-end extent invariant of one candidate file.
 *
 * Whatever survives `gguf_validate_tensors` must have every declared tensor
 * readable in full through `GgufReader`, and whatever does not must be refused
 * there. This is the property that keeps a hostile extent from producing an
 * out-of-bounds read or a short, silently-accepted payload.
 *
 * @param[in] path File to open from disk.
 * @param[in] what Case label printed on failure.
 */
void expect_reader_consistent(const std::filesystem::path& path, const char* what) {
    rocminfer::GgufReader reader;
    const int open_status = reader.open(path.string().c_str());
    if (open_status != 0) {
        ++g_cases;
        return;  // Refused at the door; nothing further can be checked.
    }
    ++g_cases;

    const rocminfer::GgufFile& manifest = reader.manifest();
    if (std::cmp_not_equal(manifest.tensors.size(), manifest.tensor_count)) {
        std::fprintf(stderr, "FAIL: %s tensor table incomplete\n", what);
        ++g_failures;
    }
    if (std::cmp_not_equal(manifest.metadata.size(), manifest.metadata_kv_count)) {
        std::fprintf(stderr, "FAIL: %s metadata table incomplete\n", what);
        ++g_failures;
    }

    for (const rocminfer::GgufTensorInfo& info : manifest.tensors) {
        std::vector<std::uint8_t> payload;
        const int read_status = reader.read_tensor(info, &payload);
        if (read_status != 0) {
            if (!payload.empty()) {
                std::fprintf(stderr, "FAIL: %s rejected read left %zu bytes behind\n", what,
                             payload.size());
                ++g_failures;
            }
            continue;
        }
        if (payload.size() != info.byte_size) {
            std::fprintf(stderr, "FAIL: %s read %zu bytes for a declared %llu\n", what,
                         payload.size(),
                         static_cast<unsigned long long>(info.byte_size));
            ++g_failures;
        }
    }
    reader.close();
    CHECK(!reader.is_open());
}

// ---------------------------------------------------------------------------
// GGUF reference files
// ---------------------------------------------------------------------------

/**
 * @brief A well-formed file: one ROCmFP4 tensor of 32 elements, one string key.
 *
 * The payload is exactly the 18 bytes the tensor declares, so the file is
 * internally consistent and every site the driver corrupts afterwards is a
 * genuine deviation from a valid file.
 */
AssembledGguf wellformed_file() {
    HeaderSpec header;
    header.version = 3;
    header.tensor_count = 1;
    header.kv_count = 1;

    std::vector<MetadataSpec> metadata(1);
    metadata[0].key = "general.architecture";
    metadata[0].raw_type =
        static_cast<std::uint32_t>(rocminfer::GgufValueType::kString);
    metadata[0].string_value = "fuzzarch";

    std::vector<TensorSpec> tensors(1);
    tensors[0].name = "blk.0.attn_q.weight";
    tensors[0].n_dims = 1;
    tensors[0].dim = rocminfer::QK_ROCMFP4;
    tensors[0].type_id = static_cast<std::uint32_t>(rocminfer::GgmlType::kQ4_0RocmFP4);
    tensors[0].offset = 0;

    return assemble_gguf(header, metadata, tensors, rocminfer::QK_ROCMFP4_BYTES);
}

/**
 * @brief A metadata-only file: two scalar key/value pairs and no tensors.
 *
 * This is the shape that legitimately parses once its structure is complete, so
 * it separates "the parser consumed the whole declared structure" from "the
 * parser stopped early because a field was missing".
 */
AssembledGguf metadata_only_file() {
    HeaderSpec header;
    header.version = 3;
    header.tensor_count = 0;
    header.kv_count = 2;

    std::vector<MetadataSpec> metadata(2);
    metadata[0].key = "general.block_count";
    metadata[0].raw_type = static_cast<std::uint32_t>(rocminfer::GgufValueType::kUint32);
    metadata[0].scalar = 2;
    metadata[1].key = "fuzz.embedding_length";
    metadata[1].raw_type = static_cast<std::uint32_t>(rocminfer::GgufValueType::kUint32);
    metadata[1].scalar = 512;

    return assemble_gguf(header, metadata, {}, 0);
}

/**
 * @brief A zero-tensor, zero-metadata file: the 24-byte header and nothing else.
 */
AssembledGguf zero_tensor_file() {
    HeaderSpec header;
    header.version = 3;
    header.tensor_count = 0;
    header.kv_count = 0;
    return assemble_gguf(header, {}, {}, 0);
}

// ---------------------------------------------------------------------------
// GGUF: entry-point boundaries
// ---------------------------------------------------------------------------

/// Feed nil and empty arguments to every manifest entry point.
void test_gguf_boundary_arguments() {
    rocminfer::GgufFile file;
    expect_reject(rocminfer::gguf_parse(nullptr, nullptr, 0), EINVAL, "gguf_parse(null,null,0)");
    expect_reject(rocminfer::gguf_parse(&file, nullptr, 0), EINVAL, "gguf_parse(file,null,0)");
    expect_reject(rocminfer::gguf_parse(&file, nullptr, 16), EINVAL,
                  "gguf_parse(file,null,16)");
    const AssembledGguf good = wellformed_file();
    expect_reject(rocminfer::gguf_parse(&file, good.bytes.data(), 0), EINVAL,
                  "gguf_parse(file,data,0)");
    expect_reject(rocminfer::gguf_parse(&file, nullptr, good.bytes.size()), EINVAL,
                  "gguf_parse(file,null,size)");

    rocminfer::GgufReader reader;
    expect_reject(reader.open(nullptr), EINVAL, "GgufReader::open(nullptr)");
    expect_reject(reader.open(""), ENOENT, "GgufReader::open(empty path)");
}

// ---------------------------------------------------------------------------
// GGUF: truncation at every byte offset
// ---------------------------------------------------------------------------

/**
 * @brief Truncate a GGUF file at every offset and require explicit rejection.
 *
 * A truncation that the parser accepts must have consumed the entire declared
 * structure, which is the only way a shorter buffer can be a valid manifest.
 * A file that declares tensors and is missing payload must then be refused by
 * `gguf_validate_tensors`.
 *
 * @param[in] file    Candidate to truncate, with its field map.
 * @param[in] label   Label printed in the per-field coverage report.
 * @param[in,out] cases   Per-role case counts, accumulated across files.
 * @param[in,out] rejects Per-role rejection counts, accumulated across files.
 * @param[in,out] tolerated Per-role counts of cuts that are legal manifests,
 *                         accumulated across files.
 */
void sweep_truncations(const AssembledGguf& file, const char* label,
                       std::array<std::uint64_t,
                                  static_cast<std::size_t>(FieldRole::kRoleCount)>& cases,
                       std::array<std::uint64_t,
                                  static_cast<std::size_t>(FieldRole::kRoleCount)>& rejects,
                       std::array<std::uint64_t,
                                  static_cast<std::size_t>(FieldRole::kRoleCount)>& tolerated) {
    for (std::size_t cut = 1; cut < file.bytes.size(); ++cut) {
        const std::vector<std::uint8_t> truncated(file.bytes.begin(),
                                                  file.bytes.begin() +
                                                      static_cast<std::ptrdiff_t>(cut));
        const FieldRole role = file.roles[cut - 1];
        const std::size_t role_index = static_cast<std::size_t>(role);
        ++cases[role_index];

        rocminfer::GgufFile parsed;
        const int status = rocminfer::gguf_parse(&parsed, truncated.data(), truncated.size());
        if (status != 0) {
            if (status != ERANGE && status != EINVAL) {
                std::fprintf(stderr, "FAIL: %s cut %zu returned %d, expected %d or %d\n", label,
                             cut, status, ERANGE, EINVAL);
                ++g_failures;
            }
            ++rejects[role_index];
            continue;
        }

        if (cut < file.structure_end) {
            std::fprintf(stderr,
                         "FAIL: %s cut %zu was accepted although the declared structure "
                         "extends to %zu\n",
                         label, cut, file.structure_end);
            ++g_failures;
            continue;
        }

        if (std::cmp_not_equal(parsed.tensors.size(), parsed.tensor_count) ||
            std::cmp_not_equal(parsed.metadata.size(), parsed.metadata_kv_count)) {
            std::fprintf(stderr, "FAIL: %s cut %zu parsed an incomplete table\n", label, cut);
            ++g_failures;
            continue;
        }

        if (parsed.tensors.empty()) {
            ++tolerated[role_index];
            continue;
        }

        const int validate_status =
            rocminfer::gguf_validate_tensors(parsed, truncated.size(), truncated.size());
        if (validate_status != ERANGE) {
            std::fprintf(stderr,
                         "FAIL: %s cut %zu dropped payload bytes yet validated with %d\n",
                         label, cut, validate_status);
            ++g_failures;
            continue;
        }
        ++rejects[role_index];
    }
}

/// Run the truncation sweep over the three reference shapes and report coverage.
void test_gguf_truncation_every_offset() {
    const AssembledGguf wellformed = wellformed_file();
    const AssembledGguf metadata_only = metadata_only_file();
    const AssembledGguf zero_tensor = zero_tensor_file();
    const AssembledGguf all[] = {wellformed, metadata_only, zero_tensor};
    const char* labels[] = {"wellformed", "metadata-only", "zero-tensor"};

    constexpr std::size_t kRoleCount = static_cast<std::size_t>(FieldRole::kRoleCount);
    std::array<std::uint64_t, kRoleCount> cases{};
    std::array<std::uint64_t, kRoleCount> rejects{};
    std::array<std::uint64_t, kRoleCount> tolerated{};

    for (std::size_t i = 0; i < 3; ++i) {
        sweep_truncations(all[i], labels[i], cases, rejects, tolerated);
    }

    for (std::size_t role = 0; role < kRoleCount; ++role) {
        if (cases[role] == 0) {
            continue;
        }
        std::printf("  truncation %-15s %6llu cuts, %6llu rejected, %6llu valid-manifest\n",
                    role_name(static_cast<FieldRole>(role)),
                    static_cast<unsigned long long>(cases[role]),
                    static_cast<unsigned long long>(rejects[role]),
                    static_cast<unsigned long long>(tolerated[role]));
    }
}

// ---------------------------------------------------------------------------
// GGUF: structural corruption
// ---------------------------------------------------------------------------

/**
 * @brief Corrupt every byte of a file with hostile values and require safety.
 *
 * Whatever the parser accepts must be internally consistent: complete tables,
 * dimensions the reader supports, and no tensor whose declared extent falls
 * outside the file. Anything else is refused.
 */
void test_gguf_structural_corruption() {
    const AssembledGguf good = wellformed_file();
    static const std::uint8_t kHostile[] = {0x00u, 0xFFu, 0x7Fu, 0x80u};

    for (std::size_t position = 0; position < good.bytes.size(); ++position) {
        for (std::uint8_t replacement : kHostile) {
            if (good.bytes[position] == replacement) {
                continue;
            }
            std::vector<std::uint8_t> bytes = good.bytes;
            bytes[position] = replacement;

            rocminfer::GgufFile file;
            char label[96];
            std::snprintf(label, sizeof(label), "corrupt byte %zu to 0x%02X", position,
                          replacement);
            const int parse_status = rocminfer::gguf_parse(&file, bytes.data(), bytes.size());
            if (parse_status != 0) {
                if (parse_status != ERANGE && parse_status != EINVAL) {
                    std::fprintf(stderr, "FAIL: %s returned %d, expected %d or %d\n", label,
                                 parse_status, ERANGE, EINVAL);
                    ++g_failures;
                }
                ++g_cases;
                continue;
            }
            ++g_cases;

            if (std::cmp_not_equal(file.tensors.size(), file.tensor_count) ||
                std::cmp_not_equal(file.metadata.size(), file.metadata_kv_count)) {
                std::fprintf(stderr, "FAIL: %s produced an incomplete table\n", label);
                ++g_failures;
            }
            for (const rocminfer::GgufTensorInfo& info : file.tensors) {
                if (info.dimensions.size() > 4) {
                    std::fprintf(stderr, "FAIL: %s produced %zu dimensions\n", label,
                                 info.dimensions.size());
                    ++g_failures;
                }
                if (info.byte_size > 0 &&
                    info.offset + info.byte_size > bytes.size() - file.data_offset) {
                    std::fprintf(stderr, "FAIL: %s declared an extent outside the file\n",
                                 label);
                    ++g_failures;
                }
            }

            const int validate_status =
                rocminfer::gguf_validate_tensors(file, bytes.size(), bytes.size());
            if (validate_status != 0 && validate_status != ERANGE) {
                std::fprintf(stderr, "FAIL: %s validated with %d\n", label, validate_status);
                ++g_failures;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// GGUF: unknown types and absurd fields
// ---------------------------------------------------------------------------

/**
 * @brief Build one copy of the well-formed tensor table with a patched field.
 * @param[in] field_offset Offset of the field inside `good.bytes`.
 * @param[in] value        Bytes to write at that offset.
 * @return A copy of the well-formed file with the field replaced.
 */
std::vector<std::uint8_t> patch_field(const AssembledGguf& good, std::size_t field_offset,
                                      const std::vector<std::uint8_t>& value) {
    std::vector<std::uint8_t> bytes = good.bytes;
    for (std::size_t i = 0; i < value.size() && field_offset + i < bytes.size(); ++i) {
        bytes[field_offset + i] = value[i];
    }
    return bytes;
}

/// Patch a 32-bit little-endian field in a copy of the well-formed file.
std::vector<std::uint8_t> patch_u32(const AssembledGguf& good, std::size_t field_offset,
                                   std::uint32_t value) {
    const std::vector<std::uint8_t> raw = {static_cast<std::uint8_t>(value & 0xFFu),
                                           static_cast<std::uint8_t>((value >> 8) & 0xFFu),
                                           static_cast<std::uint8_t>((value >> 16) & 0xFFu),
                                           static_cast<std::uint8_t>((value >> 24) & 0xFFu)};
    return patch_field(good, field_offset, raw);
}

/// Patch a 64-bit little-endian field in a copy of the well-formed file.
std::vector<std::uint8_t> patch_u64(const AssembledGguf& good, std::size_t field_offset,
                                   std::uint64_t value) {
    std::vector<std::uint8_t> raw(8, 0);
    for (std::size_t i = 0; i < raw.size(); ++i) {
        raw[i] = static_cast<std::uint8_t>((value >> (8u * i)) & 0xFFu);
    }
    return patch_field(good, field_offset, raw);
}

/// Feed unknown value types, unknown tensor types, and absurd field values.
void test_gguf_unknown_and_absurd_fields() {
    const AssembledGguf good = wellformed_file();

    // Unknown metadata value types must be refused, not defaulted.
    static const std::uint32_t kUnknownValueTypes[] = {
        13u, 14u, 15u, 16u, 31u, 32u, 100u, 0x7FFFFFFFu, 0x80000000u, 0xFFFFFFFFu};
    for (std::uint32_t raw_type : kUnknownValueTypes) {
        const std::vector<std::uint8_t> bytes =
            patch_u32(good, good.kv_field_offsets[1], raw_type);
        expect_parse_reject(bytes, "unknown metadata value type");
    }

    // Unknown array element types must be refused too.
    static const std::uint32_t kUnknownElementTypes[] = {13u, 14u, 32u, 0xFFFFFFFFu};
    for (std::uint32_t raw_type : kUnknownElementTypes) {
        MetadataSpec entry;
        entry.key = "fuzz.table";
        entry.raw_type = static_cast<std::uint32_t>(rocminfer::GgufValueType::kArray);
        entry.array_element_type = raw_type;
        entry.array_length = 4;
        entry.array_bytes.assign(32, 0x5A);

        HeaderSpec header;
        header.tensor_count = 0;
        header.kv_count = 1;
        expect_parse_reject(assemble_gguf(header, {entry}, {}, 0).bytes,
                            "unknown array element type");
    }

    // Absurd declared counts must be refused before any table work.
    static const std::uint64_t kAbsurdCounts[] = {
        (1ull << 30), (1ull << 34), (1ull << 40), (1ull << 62),
        0x7FFFFFFFFFFFFFFFull, 0x8000000000000000ull, 0xFFFFFFFFFFFFFFFEull,
        0xFFFFFFFFFFFFFFFFull};
    for (std::uint64_t count : kAbsurdCounts) {
        HeaderSpec header;
        header.tensor_count = count;
        header.kv_count = 0;
        expect_parse_reject(assemble_gguf(header, {}, {}, 0).bytes, "absurd tensor count");

        header.tensor_count = 0;
        header.kv_count = count;
        expect_parse_reject(assemble_gguf(header, {}, {}, 0).bytes, "absurd metadata count");
    }

    // Absurd string and array lengths must be refused before any allocation.
    static const std::uint64_t kAbsurdLengths[] = {(1ull << 30), (1ull << 40), (1ull << 50),
                                                   (1ull << 62), 0xFFFFFFFFFFFFFFFFull};
    for (std::uint64_t length : kAbsurdLengths) {
        const std::vector<std::uint8_t> bytes =
            patch_u64(good, good.length_prefixes[0], length);
        expect_parse_reject(bytes, "absurd key length");

        std::vector<std::uint8_t> value_bytes = patch_u64(good, good.length_prefixes[1], length);
        expect_parse_reject(value_bytes, "absurd tensor-name length");
    }
    for (std::uint64_t length : kAbsurdLengths) {
        MetadataSpec entry;
        entry.key = "fuzz.table";
        entry.raw_type = static_cast<std::uint32_t>(rocminfer::GgufValueType::kArray);
        entry.array_element_type = static_cast<std::uint32_t>(rocminfer::GgufValueType::kUint8);
        entry.array_length = length;
        entry.array_bytes.assign(32, 0x33);

        HeaderSpec header;
        header.tensor_count = 0;
        header.kv_count = 1;
        expect_parse_reject(assemble_gguf(header, {entry}, {}, 0).bytes,
                            "absurd array length");
    }

    // A dimension count above the container maximum must be refused.
    static const std::uint32_t kAbsurdDimCounts[] = {5u, 6u, 255u, 0xFFFFFFFFu};
    for (std::uint32_t n_dims : kAbsurdDimCounts) {
        const std::vector<std::uint8_t> bytes =
            patch_u32(good, good.tensor_field_offsets[1], n_dims);
        expect_parse_reject(bytes, "absurd dimension count");
    }

    // A zero or wrapped dimension must be refused, never sized as zero bytes.
    static const std::uint64_t kAbsurdDims[] = {0ull, 1ull << 62, 1ull << 63,
                                                0x7FFFFFFFFFFFFFFFull, 0x8000000000000000ull,
                                                0xFFFFFFFFFFFFFFFEull, 0xFFFFFFFFFFFFFFFFull};
    for (std::uint64_t dim : kAbsurdDims) {
        std::vector<std::uint8_t> bytes = patch_u64(good, good.tensor_field_offsets[2], dim);
        // The declared extent has to be refused for the ROCmFP4 family no matter
        // how the byte-size product behaves, because the payload is 18 bytes.
        expect_validate_reject(bytes, "absurd dimension extent");
    }

    // An offset past the end of the file must be refused.
    static const std::uint64_t kAbsurdOffsets[] = {1ull, 18ull, 1ull << 32, 1ull << 62,
                                                   0xFFFFFFFFFFFFFFFFull};
    for (std::uint64_t offset : kAbsurdOffsets) {
        const std::vector<std::uint8_t> bytes =
            patch_u64(good, good.tensor_field_offsets[4], offset);
        expect_validate_reject(bytes, "absurd tensor offset");
    }

    // Unknown tensor types are skipped rather than approximated, so they must
    // validate without ever being given a byte size.
    static const std::uint32_t kUnknownTensorTypes[] = {2u,  3u,  4u,  5u,  6u,  7u,  8u,
                                                        9u,  12u, 13u, 30u, 50u, 99u, 200u,
                                                        999u, 0xFFFFFFFFu};
    for (std::uint32_t type_id : kUnknownTensorTypes) {
        const std::vector<std::uint8_t> bytes =
            patch_u32(good, good.tensor_field_offsets[3], type_id);
        rocminfer::GgufFile file;
        char label[64];
        std::snprintf(label, sizeof(label), "unknown tensor type %u", type_id);
        expect_reject(rocminfer::gguf_parse(&file, bytes.data(), bytes.size()), 0, label);
        ++g_cases;
        if (!file.tensors.empty() && file.tensors[0].byte_size != 0) {
            std::fprintf(stderr, "FAIL: %s was assigned %llu bytes instead of being skipped\n",
                         label, static_cast<unsigned long long>(file.tensors[0].byte_size));
            ++g_failures;
        }
        const int validate_status =
            rocminfer::gguf_validate_tensors(file, bytes.size(), bytes.size());
        if (validate_status != 0 && validate_status != ERANGE) {
            std::fprintf(stderr, "FAIL: %s validated with %d\n", label, validate_status);
            ++g_failures;
        }
    }

    // Unsupported versions and a damaged magic must be refused outright, and
    // `gguf_parse` reports both as EINVAL rather than ERANGE, because a bad magic
    // and an unsupported version are invalid input rather than a short buffer. The
    // version is the second header word, so its offset is the one recorded for the
    // magic field.
    static const std::uint32_t kBadVersions[] = {0u, 1u, 4u, 5u, 99u, 0xFFFFFFFFu};
    for (std::uint32_t version : kBadVersions) {
        const std::vector<std::uint8_t> bytes =
            patch_u32(good, good.header_offsets.at(1), version);
        rocminfer::GgufFile file;
        expect_reject(rocminfer::gguf_parse(&file, bytes.data(), bytes.size()), EINVAL,
                      "unsupported version");
    }
    for (std::size_t byte = 0; byte < 4; ++byte) {
        const std::vector<std::uint8_t> bytes = patch_field(good, byte, {static_cast<std::uint8_t>('X')});
        rocminfer::GgufFile file;
        expect_reject(rocminfer::gguf_parse(&file, bytes.data(), bytes.size()), EINVAL,
                      "broken magic");
    }
}

/**
 * @brief Write one candidate file verbatim for the on-disk reader boundary.
 * @param[in] path  Destination path; its parent directory must already exist.
 * @param[in] bytes Candidate file bytes, written unmodified.
 * @return true when every byte reached the file and the stream closed without
 *         error; false otherwise.
 * @pre `path` names a writable location outside the repository.
 * @post The file holds exactly `bytes.size()` bytes, or the write failed and the
 *       caller must not treat the file as an evaluated case.
 * @note The buffer is handed to the stream through a `const void*` so the copy
 *       needs no unsigned-char to char reinterpretation.
 * @warning A failure is reported to the caller instead of being retried, because
 *          a candidate that never reached disk cannot be checked at all.
 */
bool write_probe(const std::filesystem::path& path, const std::vector<std::uint8_t>& bytes) {
    std::ofstream stream(path, std::ios::binary | std::ios::trunc);
    if (!stream.is_open()) {
        return false;
    }
    if (!bytes.empty()) {
        const void* source = bytes.data();
        stream.write(static_cast<const char*>(source),
                     static_cast<std::streamsize>(bytes.size()));
    }
    stream.close();
    return !stream.fail();
}

/**
 * @brief Hold the on-disk reader to the end-to-end extent invariant.
 *
 * A manifest that survives `gguf_parse` inside `GgufReader::open` must have every
 * declared tensor fully readable through `GgufReader::read_tensor`, and a tensor
 * that is not must be refused there with nothing left behind in the output
 * buffer. Every cut length of every reference shape is written to disk once and
 * read back, so the invariant is checked against a real file rather than against
 * the in-memory buffer the parser also saw.
 *
 * @post `g_cases` counts one on-disk probe per cut length per shape, and
 *       `g_failures` counts every tensor read that disagreed with its declared
 *       extent.
 * @note A file refused at the door counts as a rejected case and cannot be
 *       checked further, which is why the helper tolerates a non-zero `open`
 *       status while still counting the probe.
 * @warning The probe file lives in the system temporary directory and is removed
 *          on every exit path, so no candidate is ever written into the
 *          repository tree.
 */
void test_gguf_reader_on_disk_boundary() {
    const AssembledGguf shapes[] = {wellformed_file(), metadata_only_file(),
                                    zero_tensor_file()};
    const char* labels[] = {"wellformed", "metadata-only", "zero-tensor"};
    const std::filesystem::path probe =
        std::filesystem::temp_directory_path() / "rocminfer_fuzz_probe.gguf";

    for (std::size_t shape = 0; shape < 3; ++shape) {
        const AssembledGguf& file = shapes[shape];
        for (std::size_t cut = 1; cut <= file.bytes.size(); ++cut) {
            const std::vector<std::uint8_t> candidate(
                file.bytes.begin(), file.bytes.begin() + static_cast<std::ptrdiff_t>(cut));
            if (!write_probe(probe, candidate)) {
                std::fprintf(stderr, "FAIL: %s cut %zu never reached %s\n", labels[shape], cut,
                             probe.string().c_str());
                ++g_failures;
                std::remove(probe.string().c_str());
                return;
            }
            char label[96];
            std::snprintf(label, sizeof(label), "%s cut %zu", labels[shape], cut);
            expect_reader_consistent(probe, label);
        }
    }
    std::remove(probe.string().c_str());
}

/**
 * @brief Exhaust all 256 ROCmFP4 scale bytes in both packing layouts.
 *
 * Unsigned E4M3 reserves byte `0x7F` for NaN and no byte with the sign bit set
 * is a scale at all, so validity is exactly `e <= 0x7E`. Every one of the 256
 * bytes is pushed through the reference decoder in the dual-scale layout and in
 * the FAST layout, and an invalid byte must produce EINVAL rather than a silent
 * zero scale, because a silent zero scale is indistinguishable from real data
 * that happens to be zero. Every accepted block must decode to finite weights
 * and must leave the output buffer untouched when it refuses.
 *
 * @post `g_cases` counts one probe per scale byte for the validity and finiteness
 *       claims plus one per layout for the block decode, and `g_failures` counts
 *       every expectation that did not hold.
 * @note The dual-scale layout carries two scale bytes, so the byte under test is
 *       written to both positions: a single invalid byte must refuse the block,
 *       and writing both proves neither position can mask the other.
 * @note Scale byte `0x7E` is valid yet has no table entry and decodes to zero,
 *       which zeroes the whole block. The reference reproduces that behaviour
 *       deliberately, so this driver asserts it rather than tolerating it.
 * @warning The block buffer is sized from the layout constants, never from a
 *          length read out of the data under test.
 */
void test_rocmfp4_scale_exhaustive() {
    constexpr std::uint8_t kNibbleSeed = 0x1B;
    constexpr float kWriteSentinel = -98765.5f;

    std::array<std::uint8_t, rocminfer::QK_ROCMFP4_BYTES> block{};
    for (std::size_t i = 0; i < rocminfer::QS_ROCMFP4; ++i) {
        block[i] = static_cast<std::uint8_t>(kNibbleSeed + 7u * static_cast<std::uint32_t>(i));
    }
    std::array<float, rocminfer::QK_ROCMFP4> weights{};

    for (int value = 0; value <= 0xFF; ++value) {
        const std::uint8_t e = static_cast<std::uint8_t>(value);
        const bool valid = rocminfer::rocmfp4_scale_is_valid(e);

        ++g_cases;
        CHECK(valid == (e <= rocminfer::ROCMFP4_SCALE_MAX));
        if (valid) {
            ++g_cases;
            CHECK(std::isfinite(rocminfer::rocmfp4_scale_to_float(e)));
        }

        block[rocminfer::QS_ROCMFP4] = e;
        block[rocminfer::QS_ROCMFP4 + 1u] = e;
        for (const bool dual_scale : {true, false}) {
            weights.fill(kWriteSentinel);
            const int status = rocminfer::rocmfp4_dequantize_block(weights.data(), block.data(),
                                                                  dual_scale);
            if (valid) {
                expect_accept(status, dual_scale ? "dual-scale block, valid scale byte"
                                                 : "FAST block, valid scale byte");
                if (status == 0) {
                    for (const float weight : weights) {
                        CHECK(std::isfinite(weight));
                    }
                }
            } else {
                expect_reject(status, EINVAL, dual_scale ? "dual-scale block, invalid scale byte"
                                                         : "FAST block, invalid scale byte");
                for (const float weight : weights) {
                    CHECK(weight == kWriteSentinel);
                }
            }
        }
    }

    block[rocminfer::QS_ROCMFP4] = rocminfer::ROCMFP4_SCALE_MAX;
    block[rocminfer::QS_ROCMFP4 + 1u] = rocminfer::ROCMFP4_SCALE_MAX;
    weights.fill(kWriteSentinel);
    ++g_cases;
    CHECK(rocminfer::rocmfp4_dequantize_block(weights.data(), block.data(), true) == 0);
    for (const float weight : weights) {
        CHECK(weight == 0.0f);
    }
}

/**
 * @brief Documented Codebook10 magnitude level set, indexed by magnitude code.
 *
 * The format definition names the level set `0, +/-1, +/-2, +/-3, +/-4, +/-6,
 * +/-8, +/-10` and states that the three low bits of a nibble select a magnitude
 * through the remap `M <= 4 ? M : 2*M - 4`. The magnitudes are written out here
 * rather than recomputed with the same expression the implementation uses, so a
 * wrong remap cannot hide by being wrong in both places at once.
 */
constexpr std::array<std::int8_t, 8> kCodebookMagnitudeByCode = {0, 1, 2, 3, 4, 6, 8, 10};

/**
 * @brief Independent re-derivation of the weight one packed nibble carries.
 * @param[in] nibble Packed nibble; bit 3 is the sign, bits 0..2 the magnitude.
 * @return The weight in -10..10 that the format assigns to that nibble.
 * @pre `nibble` is the four-bit code under test.
 * @post The result is always an element of the Codebook10 level set.
 * @note This is a second derivation written from the format description, not a
 *       call to `rocmfp4_decode_code`, so agreement between the two is evidence
 *       rather than a tautology.
 * @warning The sign is applied by negation, so magnitude code 0 yields zero for
 *          both the positive and the negative nibble. That is intended: the
 *          level set holds 15 values for 16 possible nibbles.
 */
std::int8_t expected_nibble_weight(std::uint8_t nibble) noexcept {
    const std::size_t code = static_cast<std::size_t>(nibble & 0x07U);
    const std::int8_t magnitude = kCodebookMagnitudeByCode[code];
    return (nibble & 0x08U) != 0U ? static_cast<std::int8_t>(-magnitude) : magnitude;
}

/**
 * @brief Decode every byte value at every byte position of a packed block.
 *
 * Each byte of a packed block carries two weights in its nibbles, and the
 * reference decoder reads weight `j` from `qs[j] & 0x0F` and weight `j + 16` from
 * `qs[j] >> 4`. So a byte written at position `p` must surface as weight `p` and
 * as weight `p + 16`, which is the only property that can prove the packing is
 * not shifted, swapped, or masked. Every one of the 256 byte values is written at
 * every byte position of both layouts and the decoded weights are cross-checked
 * against an independent re-derivation written from the format description.
 *
 * @post `g_cases` counts one probe per byte value per byte position per layout,
 *       plus one per byte value for the direct code decode, and `g_failures`
 *       counts every decoded weight that disagreed.
 * @note The block is decoded with a scale byte that expands to exactly 1.0, so
 *       the decoded weight equals the codebook value with no rounding in between
 *       and the comparison is exact. That scale byte is itself asserted to expand
 *       to 1.0 rather than assumed to.
 * @note Scale byte positions are checked for their accept-or-reject decision
 *       only; their exhaustive decode is the subject of
 *       `test_rocmfp4_scale_exhaustive`, and this section covers them so the
 *       "every byte value at every byte position" claim stays honest.
 * @warning The output buffer is pre-filled with a sentinel so a refused block
 *          must leave it untouched; a decoder that wrote before validating would
 *          be caught here.
 */
void test_rocmfp4_nibble_decode_exhaustive() {
    constexpr std::uint8_t kUnitScale = 0x40;
    constexpr float kWriteSentinel = -13579.0f;

    Lcg rng(0x00C0DE15u);
    std::array<std::uint8_t, rocminfer::QK_ROCMFP4_BYTES> block{};
    std::array<float, rocminfer::QK_ROCMFP4> weights{};

    ++g_cases;
    CHECK(rocminfer::rocmfp4_scale_to_float(kUnitScale) == 1.0f);

    for (int value = 0; value <= 0xFF; ++value) {
        const std::uint8_t q = static_cast<std::uint8_t>(value);
        ++g_cases;
        CHECK(rocminfer::rocmfp4_decode_code(q) == expected_nibble_weight(q));
    }

    for (const bool dual_scale : {true, false}) {
        const std::size_t block_bytes = dual_scale ? static_cast<std::size_t>(rocminfer::QK_ROCMFP4_BYTES)
                                                   : static_cast<std::size_t>(rocminfer::QK_ROCMFP4_FAST_BYTES);
        for (std::size_t i = 0; i < rocminfer::QS_ROCMFP4; ++i) {
            block[i] = static_cast<std::uint8_t>(rng.next() & 0xFFU);
        }
        block[rocminfer::QS_ROCMFP4 + 1u] = kUnitScale;

        for (std::size_t position = 0; position < block_bytes; ++position) {
            for (int value = 0; value <= 0xFF; ++value) {
                const std::uint8_t q = static_cast<std::uint8_t>(value);
                block[rocminfer::QS_ROCMFP4] = kUnitScale;
                block[rocminfer::QS_ROCMFP4 + 1u] = kUnitScale;
                block[position] = q;
                weights.fill(kWriteSentinel);
                const int status = rocminfer::rocmfp4_dequantize_block(weights.data(),
                                                                      block.data(), dual_scale);
                ++g_cases;
                if (position < rocminfer::QS_ROCMFP4) {
                    CHECK(status == 0);
                    CHECK(weights[position] == expected_nibble_weight(q));
                    CHECK(weights[position + rocminfer::QS_ROCMFP4] ==
                          expected_nibble_weight(static_cast<std::uint8_t>(q >> 4)));
                } else if (rocminfer::rocmfp4_scale_is_valid(q)) {
                    expect_accept(status, "scale byte position, valid byte");
                } else {
                    expect_reject(status, EINVAL, "scale byte position, invalid byte");
                    CHECK(weights[0] == kWriteSentinel);
                }
            }
        }
    }
}

/**
 * @brief Exercise every SHA-256 padding length class the message schedule reaches.
 *
 * A one-shot digest and a digest fed in chunks must agree for the same bytes,
 * which is the only property that can distinguish a correct length field and a
 * correct zero-fill from a decoder that merely happens to agree for messages
 * that fit one block. The classes are chosen so that every distinct padding path
 * is crossed: the length that leaves room for the length field, the length that
 * forces a second compression, and the lengths that land exactly on a block
 * boundary.
 *
 * @post `g_cases` counts one probe per length class per invariant plus one per
 *       pair of classes for the distinctness sweep, and `g_failures` counts every
 *       violated invariant.
 * @note No expected digest is written in this driver. The known-answer vectors
 *       produced from the standard live in `tests/test_sha256.cpp`; restating
 *       them here would be a second hand-transcribed copy of the same value,
 *       which cannot detect a wrong one. This section therefore checks the
 *       properties that do not depend on remembering a digest: the two code paths
 *       agree, the digest is stable, one flipped bit changes it, and distinct
 *       messages give distinct digests.
 * @note The prefix split is the length-extension property in its positive form:
 *       feeding a message in two pieces must land in exactly the internal state
 *       that feeding it whole reaches, which is what a wrong buffered byte count
 *       or a lost carry would break.
 * @warning A `Sha256` object is single-use per digest; this driver calls `reset`
 *          before every reuse rather than assuming a finalized context can be
 *          extended.
 */
void test_sha256_length_classes() {
    constexpr std::array<std::size_t, 13> kLengthClasses = {
        0u, 1u, 55u, 56u, 57u, 63u, 64u, 65u, 119u, 120u, 127u, 128u, 1000u};

    std::vector<std::string> digests;
    digests.reserve(kLengthClasses.size());

    for (const std::size_t length : kLengthClasses) {
        std::vector<std::uint8_t> message(length);
        Lcg rng(0x51A25600u + length);
        for (std::uint8_t& byte : message) {
            byte = static_cast<std::uint8_t>(rng.next() & 0xFFU);
        }

        const std::string one_shot = rocminfer::Sha256::hex(message.data(), message.size());
        digests.push_back(one_shot);

        ++g_cases;
        CHECK(one_shot == rocminfer::Sha256::hex(message.data(), message.size()));

        for (const std::size_t chunk : {std::size_t{1u}, std::size_t{7u}, std::size_t{64u},
                                        std::size_t{1000u}}) {
            rocminfer::Sha256 context;
            std::size_t offset = 0;
            while (offset < message.size()) {
                const std::size_t remaining = message.size() - offset;
                const std::size_t take = remaining < chunk ? remaining : chunk;
                context.update(message.data() + offset, take);
                offset += take;
            }
            ++g_cases;
            CHECK(context.hex_digest() == one_shot);
        }

        rocminfer::Sha256 split;
        split.reset();
        const std::size_t half = message.size() / 2u;
        if (!message.empty()) {
            split.update(message.data(), half);
            split.update(message.data() + half, message.size() - half);
        }
        ++g_cases;
        CHECK(split.hex_digest() == one_shot);

        rocminfer::Sha256 reused;
        const std::string finalized = reused.hex_digest();
        ++g_cases;
        CHECK(finalized.size() == 64);
        reused.reset();
        reused.update(message.data(), message.size());
        ++g_cases;
        CHECK(reused.hex_digest() == one_shot);

        if (!message.empty()) {
            std::vector<std::uint8_t> flipped = message;
            flipped[message.size() / 2u] =
                static_cast<std::uint8_t>(flipped[message.size() / 2u] ^ 0x01U);
            ++g_cases;
            CHECK(rocminfer::Sha256::hex(flipped.data(), flipped.size()) != one_shot);
        }

        ++g_cases;
        CHECK(one_shot.size() == 64);
        for (const char character : one_shot) {
            CHECK((character >= '0' && character <= '9') ||
                  (character >= 'a' && character <= 'f'));
        }
    }

    for (std::size_t i = 0; i < digests.size(); ++i) {
        for (std::size_t j = i + 1; j < digests.size(); ++j) {
            ++g_cases;
            CHECK(digests[i] != digests[j]);
        }
    }
}

/**
 * @brief Exercise the trace recorder's host path, disabled and enabled.
 *
 * A disabled recorder must record nothing at all: no allocation, no clock read,
 * no row, and a report that refuses to emit a table that would look like data.
 * An enabled recorder must aggregate host time per logical component, calibrate
 * and publish an instrumentation floor, and emit both report formats. Every
 * construction-time configuration that the contract declares invalid must be
 * refused with `std::invalid_argument` rather than clamped into a recorder that
 * silently under-reports.
 *
 * @post `g_cases` counts one probe per configuration and per aggregate claim, and
 *       `g_failures` counts every claim that did not hold.
 * @note This driver links the host-only core, whose null event pool reports
 *       device timing as unavailable, so device time must be absent here rather
 *       than fabricated. The device assertions are therefore branched on
 *       `device_timing_available()` so the check stays meaningful if the link
 *       ever changes, while `resolve_pending` is asserted to succeed because no
 *       device sample can exist to drop in this configuration.
 * @note Component labels follow the instrumentation contract's logical roles, not
 *       function names, so the aggregates can be compared across runs.
 * @warning A `TraceRecorder` must outlive every `TraceScope` opened on it; the
 *          scopes here live in nested blocks so their destructors run before the
 *          recorder's.
 */
void test_trace_recorder_host_path() {
    {
        rocminfer::TraceConfig disabled_config;
        rocminfer::TraceRecorder recorder(disabled_config);
        CHECK(!recorder.enabled());
        CHECK(recorder.report_mode() == rocminfer::TraceReport::kOff);
        CHECK(!recorder.device_timing_available());

        const rocminfer::TraceScope scope(recorder, "embed", rocminfer::TraceDomain::kHost);
        CHECK(!scope.active());

        std::vector<rocminfer::TraceRow> rows;
        CHECK(!recorder.snapshot(&rows));
        CHECK(rows.empty());
        CHECK(recorder.dropped_component_scopes() == 0);
        CHECK(recorder.dropped_pending_scopes() == 0);
        CHECK(recorder.floor_sample_count() == 0);
        CHECK(recorder.floor_host_ns() == 0);
        CHECK(recorder.floor_device_ns() == 0);

        recorder.measure_floor();
        ++g_cases;
        CHECK(recorder.floor_sample_count() == 0);

        std::ostringstream table;
        CHECK(!recorder.report(table));
        CHECK(table.str().empty());
        std::ostringstream json;
        CHECK(!recorder.report_json(json));
        CHECK(json.str().empty());
    }

    const auto refuses = [](const rocminfer::TraceConfig& config) {
        try {
            rocminfer::TraceRecorder recorder(config);
        } catch (const std::invalid_argument&) {
            return true;
        }
        return false;
    };

    rocminfer::TraceConfig base;
    base.report = rocminfer::TraceReport::kTable;

    rocminfer::TraceConfig invalid = base;
    invalid.max_components = 0;
    ++g_cases;
    CHECK(refuses(invalid));

    invalid = base;
    invalid.floor_samples = 0;
    ++g_cases;
    CHECK(refuses(invalid));

    invalid = base;
    invalid.device_event_pool = 1;
    ++g_cases;
    CHECK(refuses(invalid));

    invalid = base;
    invalid.device_event_pool = 3;
    ++g_cases;
    CHECK(refuses(invalid));

    invalid = base;
    invalid.report = rocminfer::TraceReport::kOff;
    invalid.max_components = 0;
    ++g_cases;
    CHECK(refuses(invalid));

    rocminfer::TraceConfig minimal;
    minimal.report = rocminfer::TraceReport::kTable;
    minimal.max_components = 1;
    minimal.floor_samples = 1;
    minimal.device_event_pool = 2;
    rocminfer::TraceRecorder minimal_recorder(minimal);
    CHECK(minimal_recorder.enabled());
    minimal_recorder.measure_floor();
    ++g_cases;
    CHECK(minimal_recorder.floor_sample_count() == 1);

    rocminfer::TraceConfig config;
    config.report = rocminfer::TraceReport::kTable;
    config.max_components = 4;
    config.floor_samples = 64;
    config.device_event_pool = 4;
    rocminfer::TraceRecorder recorder(config);
    CHECK(recorder.enabled());
    CHECK(recorder.report_mode() == rocminfer::TraceReport::kTable);

    constexpr int kEmbedScopes = 16;
    constexpr int kSampleScopes = 4;
    for (int i = 0; i < kEmbedScopes; ++i) {
        const rocminfer::TraceScope scope(recorder, "embed", rocminfer::TraceDomain::kHost);
        CHECK(scope.active());
    }
    for (int i = 0; i < kSampleScopes; ++i) {
        const rocminfer::TraceScope scope(recorder, "head+sample", rocminfer::TraceDomain::kHost);
        CHECK(scope.active());
    }

    std::vector<rocminfer::TraceRow> rows;
    CHECK(recorder.snapshot(&rows));
    CHECK(rows.size() == 2);
    const auto row_for = [&rows](const char* name) -> const rocminfer::TraceRow* {
        for (const rocminfer::TraceRow& row : rows) {
            if (std::strcmp(row.component, name) == 0) {
                return &row;
            }
        }
        return nullptr;
    };

    const rocminfer::TraceRow* embed = row_for("embed");
    CHECK(embed != nullptr);
    if (embed != nullptr) {
        CHECK(embed->ops == static_cast<std::uint64_t>(kEmbedScopes));
        CHECK(embed->host_ns > 0);
        CHECK(embed->dev_ns == 0);
        CHECK(embed->idle_ns == embed->host_ns);
        CHECK(embed->domain == rocminfer::TraceDomain::kHost);
    }
    const rocminfer::TraceRow* sample = row_for("head+sample");
    CHECK(sample != nullptr);
    if (sample != nullptr) {
        CHECK(sample->ops == static_cast<std::uint64_t>(kSampleScopes));
    }

    recorder.measure_floor();
    CHECK(recorder.floor_sample_count() == static_cast<std::uint32_t>(64));
    CHECK(recorder.floor_host_ns() > 0);
    if (recorder.device_timing_available()) {
        CHECK(recorder.floor_device_ns() > 0);
    } else {
        CHECK(recorder.floor_device_ns() == 0);
    }

    {
        const rocminfer::TraceScope scope(recorder, "attention", rocminfer::TraceDomain::kDevice);
        CHECK(scope.active());
    }
    rows.clear();
    CHECK(recorder.snapshot(&rows));
    const rocminfer::TraceRow* attention = row_for("attention");
    CHECK(attention != nullptr);
    if (attention != nullptr) {
        CHECK(attention->ops == 1);
        CHECK(attention->host_ns > 0);
        CHECK(attention->domain == rocminfer::TraceDomain::kDevice);
        CHECK(recorder.device_timing_available() || attention->dev_ns == 0);
    }

    CHECK(recorder.resolve_pending());
    CHECK(recorder.dropped_component_scopes() == 0);

    std::ostringstream table;
    CHECK(recorder.report(table));
    const std::string table_text = table.str();
    CHECK(table_text.find("component") != std::string::npos);
    CHECK(table_text.find("dev us") != std::string::npos);
    CHECK(table_text.find("idle us") != std::string::npos);
    CHECK(table_text.find("host us") != std::string::npos);
    CHECK(table_text.find("embed") != std::string::npos);
    CHECK(table_text.find("instrumentation floor") != std::string::npos);
    CHECK(table_text.find("empty ops timed through the same begin/end path") !=
          std::string::npos);

    std::ostringstream json;
    CHECK(recorder.report_json(json));
    const std::string json_text = json.str();
    CHECK(json_text.find("rocminfer.perftrace/1") != std::string::npos);
    CHECK(json_text.find("\"floor\"") != std::string::npos);
    CHECK(json_text.find("\"components\"") != std::string::npos);
    CHECK(json_text.find("\"embed\"") != std::string::npos);
    CHECK(json_text.find("\"dropped\"") != std::string::npos);
}

}  // namespace

/**
 * @brief Entry point of the deterministic fuzz and negative-test driver.
 * @return 0 when every malformed input was rejected explicitly, 1 otherwise.
 * @pre Every section function above has been defined in this translation unit.
 * @post The case count and the verdict are printed to stdout; a failure count is
 *       printed to stderr as it happens.
 * @note The exit code is the contract: a relaxed rejection, a tolerated default,
 *       or an out-of-bounds read must fail the run rather than pass quietly.
 */
int main() {
    test_gguf_boundary_arguments();
    test_gguf_truncation_every_offset();
    test_gguf_structural_corruption();
    test_gguf_unknown_and_absurd_fields();
    test_gguf_reader_on_disk_boundary();
    test_rocmfp4_scale_exhaustive();
    test_rocmfp4_nibble_decode_exhaustive();
    test_sha256_length_classes();
    test_trace_recorder_host_path();


    std::printf("fuzz/negative: %llu malformed inputs evaluated\n",
                static_cast<unsigned long long>(g_cases));
    if (g_failures != 0) {
        std::printf("FAILED: %d check(s)\n", g_failures);
        return 1;
    }
    std::printf("PASSED: every malformed input rejected explicitly\n");
    return 0;
}
